// Turns the planner's JSON into a flat, capped list of search queries.
// Falls back to the raw question when planning fails, so a planner outage
// degrades the research rather than ending it.
const req = $('Normalise Research Request').first().json;
const rawItem = $input.first().json;
const raw = (rawItem && rawItem.json) ? rawItem.json : rawItem;

function repairJson(text) {
  try { return JSON.parse(text); } catch (e) { /* continue */ }
  const stack = [];
  let inStr = false, esc = false, lastEnd = -1;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) { if (esc) { esc = false; } else if (c === '\\') { esc = true; } else if (c === '"') { inStr = false; } continue; }
    if (c === '"') { inStr = true; continue; }
    if (c === '{' || c === '[') { stack.push(c); }
    else if (c === '}' || c === ']') { stack.pop(); if (stack.length === 0) { lastEnd = i; } }
  }
  if (lastEnd > 0) { try { return JSON.parse(text.slice(0, lastEnd + 1)); } catch (e) { /* continue */ } }
  let patched = text;
  if (inStr) { patched += '"'; }
  patched = patched.replace(/,\s*"[^"]*"\s*:?\s*[^,{}\[\]]*$/, '').replace(/,\s*$/, '');
  for (let i = stack.length - 1; i >= 0; i--) { patched += (stack[i] === '{' ? '}' : ']'); }
  try { return JSON.parse(patched); } catch (e) { return null; }
}

let plan = null;
const notes = [];
if (raw && raw.ok && raw.output) {
  const cleaned = String(raw.output).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  plan = repairJson(cleaned);
  if (!plan) { notes.push('planner response could not be parsed even after repair; falling back to the raw question'); }
} else {
  notes.push('planner call failed: ' + ((raw && raw.error) ? raw.error : 'no output') + '; falling back to the raw question');
}

const subQuestions = (plan && Array.isArray(plan.sub_questions)) ? plan.sub_questions : [];
const queries = [];
subQuestions.forEach(function (sq) {
  (Array.isArray(sq.queries) ? sq.queries : []).forEach(function (q) {
    const text = String(q || '').trim();
    if (text && queries.length < req.max_queries) {
      queries.push({ sub_question_id: sq.id || ('SQ' + (queries.length + 1)), sub_question: sq.question || null, query: text });
    }
  });
});
if (!queries.length) {
  queries.push({ sub_question_id: 'SQ1', sub_question: req.question, query: req.question });
  notes.push('no usable queries were produced, so the question itself was used as the single query');
}

return [{
  json: {
    question: req.question,
    depth: req.depth,
    today: req.today,
    started_at_ms: req.started_at_ms,
    results_per_query: req.results_per_query,
    source_workflow: req.source_workflow,
    interpretation: plan ? (plan.interpretation || null) : null,
    feasibility_warning: plan ? (plan.feasibility_warning || null) : null,
    disconfirming_evidence: plan && Array.isArray(plan.disconfirming_evidence) ? plan.disconfirming_evidence : [],
    sub_questions: subQuestions,
    queries: queries,
    query_count: queries.length,
    planner_notes: notes,
    planner_router: { provider: raw ? raw.selected_provider : null, model: raw ? raw.selected_model : null, latency_ms: raw ? raw.latency_ms : null, estimated_cost_usd: raw ? raw.estimated_cost_usd : null }
  }
}];

// Two-stage deduplication: exact by normalised URL, then near-duplicate by
// word shingles. Search backends routinely return the same article under
// tracking parameters, syndicated copies and AMP variants.
const items = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.url; });

function normUrl(u) {
  let s = String(u).trim().toLowerCase();
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.split('#')[0];
  const parts = s.split('?');
  const path = parts[0].replace(/\/+$/, '');
  if (!parts[1]) { return path; }
  const kept = parts[1].split('&').filter(function (kv) {
    const k = kv.split('=')[0];
    return ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid', 'ref', 'source'].indexOf(k) === -1;
  }).sort();
  return kept.length ? (path + '?' + kept.join('&')) : path;
}

function shingles(text) {
  const words = String(text || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(function (w) { return w.length > 2; });
  const set = {};
  for (let i = 0; i + 2 < words.length && i < 400; i++) { set[words[i] + ' ' + words[i + 1] + ' ' + words[i + 2]] = true; }
  return Object.keys(set);
}

function jaccard(a, b) {
  if (!a.length || !b.length) { return 0; }
  const setB = {};
  b.forEach(function (x) { setB[x] = true; });
  let inter = 0;
  a.forEach(function (x) { if (setB[x]) { inter++; } });
  return inter / (a.length + b.length - inter);
}

const kept = [];
const seenUrls = {};
const duplicates = [];

items.forEach(function (it) {
  const key = normUrl(it.url);
  if (seenUrls[key]) { duplicates.push({ url: it.url, reason: 'same normalised url as ' + seenUrls[key] }); return; }
  const sh = shingles(it.content || it.snippet);
  let nearDup = null;
  for (let i = 0; i < kept.length; i++) {
    if (jaccard(sh, kept[i]._shingles) > 0.8) { nearDup = kept[i].url; break; }
  }
  if (nearDup) { duplicates.push({ url: it.url, reason: 'content is a near duplicate of ' + nearDup }); return; }
  seenUrls[key] = it.url;
  kept.push(Object.assign({}, it, { _shingles: sh }));
});

const evidence = kept.map(function (k, i) {
  return {
    id: 'S' + (i + 1),
    url: k.url,
    title: k.title,
    snippet: k.snippet,
    text: (k.content && k.content.length > 40) ? k.content : (k.snippet || ''),
    sub_question_id: k.sub_question_id,
    query: k.query
  };
});

const emptyQueries = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.empty; })
  .map(function (r) { return r.query; });

return [{
  json: {
    evidence: evidence,
    evidence_count: evidence.length,
    duplicates_removed: duplicates.length,
    duplicates: duplicates,
    queries_with_no_results: emptyQueries,
    evidence_block: evidence.map(function (e) {
      return '[' + e.id + '] ' + (e.title || 'untitled') + ' (' + e.url + ')\n' + String(e.text || '').slice(0, 2500);
    }).join('\n\n'),
    sources_json: JSON.stringify(evidence.map(function (e) { return { id: e.id, url: e.url, text: String(e.text || '').slice(0, 4000) }; }))
  }
}];

// Normalises whatever shape the search node returns into flat evidence records,
// and keeps them small so the loop context does not balloon.
const q = $('Search Loop').first().json;

function harvest(v, out, depth) {
  if (!v || depth > 4 || out.length > 40) { return; }
  if (Array.isArray(v)) { v.forEach(function (x) { harvest(x, out, depth + 1); }); return; }
  if (typeof v !== 'object') { return; }
  if (v.url && (v.title || v.description || v.markdown || v.content)) {
    out.push({
      url: String(v.url),
      title: String(v.title || '').slice(0, 300),
      snippet: String(v.description || v.snippet || '').slice(0, 600),
      content: String(v.markdown || v.content || v.text || '').slice(0, 4000)
    });
    return;
  }
  Object.keys(v).forEach(function (k) { harvest(v[k], out, depth + 1); });
}

const found = [];
$input.all().forEach(function (item) { harvest(item.json, found, 0); });

const errored = $input.all().some(function (i) { return i.json && i.json.error; });

return found.map(function (f) {
  return { json: Object.assign({}, f, { sub_question_id: q.sub_question_id, query: q.query }) };
}).concat(found.length === 0 ? [{ json: { sub_question_id: q.sub_question_id, query: q.query, url: null, title: null, snippet: null, content: null, empty: true, search_errored: errored } }] : []);

const plan = $('Parse Research Plan').first().json;
const dedup = $('Deduplicate Evidence').first().json;

function unwrap(n) {
  try { const v = $(n).first().json; return (v && v.json) ? v.json : v; } catch (e) { return null; }
}
const synth = unwrap('Synthesise Report (02 Router)');
const verification = unwrap('Verify Report (09)');
const synthPromptMeta = unwrap('Get Synthesiser Prompt (08)');
const plannerPromptMeta = unwrap('Get Planner Prompt (08)');

const noEvidence = $input.all().some(function (i) { return i.json && i.json.no_evidence; });
const reportText = (!noEvidence && synth && synth.ok) ? String(synth.output || '') : null;

// Provenance map: which source markers the report actually used, and which
// collected sources it ignored. A marker that is not in the evidence set is a
// fabrication and is listed separately.
const evidence = dedup.evidence || [];
const knownIds = evidence.map(function (e) { return e.id; });
const usedIds = [];
const unknownIds = [];
if (reportText) {
  const markers = reportText.match(/\[S\d+\]/g) || [];
  markers.forEach(function (m) {
    const id = m.slice(1, -1);
    if (knownIds.indexOf(id) !== -1) { if (usedIds.indexOf(id) === -1) { usedIds.push(id); } }
    else if (unknownIds.indexOf(id) === -1) { unknownIds.push(id); }
  });
}
const unusedIds = knownIds.filter(function (id) { return usedIds.indexOf(id) === -1; });

const costs = [];
if (plan.planner_router && plan.planner_router.estimated_cost_usd) { costs.push(Number(plan.planner_router.estimated_cost_usd)); }
if (synth && synth.estimated_cost_usd) { costs.push(Number(synth.estimated_cost_usd)); }
const totalCost = costs.reduce(function (a, b) { return a + b; }, 0);

let confidence = 'insufficient_evidence';
if (reportText && verification) {
  if (verification.verified && verification.score >= 0.85) { confidence = 'high'; }
  else if (verification.score >= 0.7) { confidence = 'medium'; }
  else { confidence = 'low'; }
}

return [{
  json: {
    generated_at: new Date().toISOString(),
    n8n_execution_id: $execution.id,
    question: plan.question,
    depth: plan.depth,
    interpretation: plan.interpretation,
    feasibility_warning: plan.feasibility_warning,
    status: noEvidence ? 'no_evidence' : (reportText ? 'complete' : 'synthesis_failed'),
    report: reportText,
    confidence: confidence,
    research: {
      sub_questions: plan.sub_questions,
      queries_run: plan.query_count,
      queries_with_no_results: dedup.queries_with_no_results || [],
      sources_collected: evidence.length,
      duplicates_removed: dedup.duplicates_removed || 0,
      planner_notes: plan.planner_notes || []
    },
    provenance: {
      sources: evidence.map(function (e) { return { id: e.id, url: e.url, title: e.title, sub_question_id: e.sub_question_id, query: e.query, cited: usedIds.indexOf(e.id) !== -1 }; }),
      markers_used: usedIds,
      sources_not_cited: unusedIds,
      fabricated_markers: unknownIds
    },
    verification: verification ? {
      verified: verification.verified, score: verification.score,
      claims_total: verification.groundedness ? verification.groundedness.claims_total : null,
      supported: verification.groundedness ? verification.groundedness.supported : null,
      contradicted: verification.groundedness ? verification.groundedness.contradicted : null,
      not_stated: verification.groundedness ? verification.groundedness.not_stated : null,
      issues: verification.issues, requires_human_review: verification.requires_human_review
    } : null,
    prompts: {
      planner: plannerPromptMeta ? { version: plannerPromptMeta.version, sha: plannerPromptMeta.sha, degraded: plannerPromptMeta.degraded } : null,
      synthesiser: synthPromptMeta ? { version: synthPromptMeta.version, sha: synthPromptMeta.sha, degraded: synthPromptMeta.degraded } : null
    },
    models: {
      planner: plan.planner_router,
      synthesiser: synth ? { provider: synth.selected_provider, model: synth.selected_model, latency_ms: synth.latency_ms, estimated_cost_usd: synth.estimated_cost_usd } : null
    },
    estimated_cost_usd_total: Math.round(totalCost * 1000000) / 1000000,
    latency_ms: plan.started_at_ms ? (Date.now() - Number(plan.started_at_ms)) : null
  }
}];
